package dev.mcpmcp.forge;
import com.google.gson.*;import dev.mcpmcp.core.*;import dev.mcpmcp.api.*;
import net.minecraft.client.Minecraft;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.fml.common.Mod;import net.minecraftforge.event.TickEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.loading.FMLPaths;import net.minecraft.network.chat.Component;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import org.slf4j.Logger;import com.mojang.logging.LogUtils;
@Mod.EventBusSubscriber(modid="mcpmcp",value=Dist.CLIENT)
public final class Runtime {
 private static final Logger LOG=LogUtils.getLogger();private static volatile Configuration config;private static LocalServer server;private static PluginManager plugins;private static final Jobs jobs=new Jobs();private static final ArrayBlockingQueue<Request> requests=new ArrayBlockingQueue<>(64);private static long epoch,ticks,lastReload,lastDebug;private static Object level;private static boolean initialized,javaLoaded,pumping,pluginsReloadPending;public static String recoveryError;private static String configError;private static final Path configFile=FMLPaths.CONFIGDIR.get().resolve("mcpmcp.json");
 private record Request(String method,JsonObject args,CompletableFuture<JsonObject> response){}
 public static synchronized void initialize(){if(initialized)return;initialized=true;try{config=Configuration.load(configFile);plugins=new PluginManager(FMLPaths.GAMEDIR.get().resolve("MCPMCP-Plugin"));plugins.overrides(()->config.pluginOverrides);plugins.setContext(new PluginContext(){public void action(String n,JsonObject s,String t,String p,Handler h){throw new UnsupportedOperationException();}public void observer(String k,int priority,Handler h){throw new UnsupportedOperationException();}public JsonObject execute(String action,JsonObject args){return Runtime.execute(action,args,UUID.randomUUID().toString());}public JsonObject observe(String kind,JsonObject args){return observation(kind,args);}});server=new LocalServer(config.port,()->config.token,Runtime::enqueue);LOG.info("MCPMCP ready on loopback port {} (no token logged)",config.port);java.lang.Runtime.getRuntime().addShutdownHook(new Thread(()->{if(server!=null)server.close();},"mcpmcp-shutdown"));}catch(Exception e){configError=e.toString();LOG.error("MCPMCP initialization failed",e);}}
 public static Configuration config(){if(config==null)throw new IllegalStateException("configuration_not_initialized");return config;}
 public static void saveConfig(){try{jobs.cancelAll();Actions.stop();config.save(configFile);}catch(Exception e){configError=e.toString();}}
 private static JsonObject enqueue(String method,JsonObject args){CompletableFuture<JsonObject> response=new CompletableFuture<>();Request request=new Request(method,args.deepCopy(),response);if(!requests.offer(request))return Jsons.error("request_queue_full");try{return response.get(15,TimeUnit.SECONDS);}catch(TimeoutException ex){requests.remove(request);response.cancel(false);return Jsons.error("client_thread_timeout");}catch(Exception e){return Jsons.error("request_interrupted");}}
 @SubscribeEvent(priority=net.minecraftforge.eventbus.api.EventPriority.LOWEST) public static void movementInput(net.minecraftforge.client.event.MovementInputUpdateEvent e){Actions.updateInput(e.getInput());}
 @SubscribeEvent public static void screenOpening(net.minecraftforge.client.event.ScreenEvent.Opening e){ContainerSessions.screenOpened(e.getNewScreen());}
 @SubscribeEvent public static void interactionInput(net.minecraftforge.client.event.InputEvent.InteractionKeyMappingTriggered e){if(e.isUseItem())ContainerSessions.manualInteraction();}
 @SubscribeEvent public static void clientTick(TickEvent.ClientTickEvent e){if(e.phase==TickEvent.Phase.END)pump(true);}
 @SubscribeEvent public static void renderTick(TickEvent.RenderTickEvent e){if(e.phase==TickEvent.Phase.END)pump(false);}
 private static void pump(boolean clientTick){if(pumping||config==null)return;pumping=true;try{pumpOnce(clientTick);}finally{pumping=false;}}
 private static void pumpOnce(boolean clientTick){if(config==null)return;Minecraft mc=Minecraft.getInstance();if(mc.level!=level){level=mc.level;epoch++;jobs.cancelAll();Actions.stop();PacketService.connectionChanged();}if(!javaLoaded){javaLoaded=true;ChatLog.init();plugins.reload();plugins.loadTrustedJavaOnce();}int processed=0;while(processed++<8){Request r=requests.poll();if(r==null)break;if(r.response.isCancelled())continue;try{r.response.complete(call(r.method,r.args));}catch(Exception e){r.response.complete(Jsons.obj("error","request_failed","reason",e.getClass().getSimpleName()+": "+Objects.toString(e.getMessage(),"")));LOG.warn("MCPMCP request {} failed",r.method,e);}}
  if(clientTick||mc.level==null||mc.isPaused()){ChatLog.captureDisplayed();ContainerSessions.pumpRecovery();if(!ContainerSessions.recoveryActive())jobs.pump(epoch);ticks++;}if(clientTick)PacketService.attach();long now=System.currentTimeMillis();if(now-lastReload>1000){lastReload=now;try{Configuration fresh=Configuration.load(configFile);if(!fresh.mode.equals(config.mode)||!fresh.transport.equals(config.transport)){jobs.cancelAll();Actions.stop();}boolean overridesChanged=!fresh.pluginOverrides.equals(config.pluginOverrides);if(fresh.port!=config.port)configError="port_change_requires_restart";fresh.port=config.port;config=fresh;if(overridesChanged){jobs.cancelAll();Actions.stop();pluginsReloadPending=true;}if(pluginsReloadPending)pluginsReloadPending=plugins.reload().has("error");}catch(Exception e){configError="invalid_config_retained";}}}
 public static JsonObject status(){Minecraft mc=Minecraft.getInstance();return Jsons.obj("name","MCP Minecraft Plus","version","0.1.2","minecraft","1.20.1","loader","forge","lifecycle",mc.level!=null?(mc.isPaused()?"paused":"in_world"):mc.screen==null?"starting":"main_menu","connected",mc.getConnection()!=null,"world_epoch",epoch,"configuration",config.publicView(),"config_error",configError,"client_thread",Thread.currentThread().getName(),"queue_size",requests.size(),"recovery_active",ContainerSessions.recoveryActive(),"recovery_error",recoveryError,"jei_required",false,"baritone_present",present("baritone.api.BaritoneAPI"),"plugin_status",plugins.status());}
 public static JsonObject call(String method,JsonObject args){return switch(method){case "status"->status();case "capabilities"->Capabilities.list();case "describe"->Capabilities.describe(Jsons.str(args,"action",""));case "observe"->observation(Jsons.str(args,"kind",""),Jsons.object(args,"arguments"));case "execute"->execute(Jsons.str(args,"action",""),Jsons.object(args,"arguments"),Jsons.str(args,"action_id",UUID.randomUUID().toString()));case "job"->jobs.result(Jsons.str(args,"action_id",""));case "cancel"->jobs.cancel(Jsons.str(args,"action_id",""));case "plugins"->plugins.status();case "plugins.reload"->{jobs.cancelAll();yield plugins.reload();}case "plugins.read"->plugins.readFile(Jsons.str(args,"path",""));case "plugins.write"->plugins.writeFile(Jsons.str(args,"path",""),Jsons.str(args,"text",""));default->Jsons.error("unknown_method");};}
 public static JsonObject observation(String kind,JsonObject args){Schema.bounded(args);JsonObject result;if(kind.equals("context"))result=ContextObservation.read();else if(Set.of("packets","packet","packet_capture").contains(kind))result=PacketService.read(kind,args);else if(kind.equals("container")){Minecraft mc=Minecraft.getInstance();result=mc.player==null?Jsons.error("not_in_world"):Jsons.obj("data",ContainerSessions.snapshot(mc.player.containerMenu));}else result=plugins.observe(kind,args).orElseGet(()->Observations.read(kind,args));result.addProperty("world_epoch",epoch);return result;}
 public static JsonObject execute(String action,JsonObject args,String id){Schema.bounded(args);if(action.equals("stop")){jobs.cancelAll();Actions.stop();return Jsons.obj("action_id",id,"status","observed_success");}JsonObject spec=Capabilities.describe(action);if(spec.has("error"))return spec;String actual=plugins.hasAction(action)?Jsons.str(spec,"transport","packet"):Actions.transport(action);String permission=plugins.hasAction(action)?Jsons.str(spec,"permission","normal"):Actions.permission(action);if(!Policy.allowed(config.mode,config.transport,actual,permission))return Jsons.obj("error","policy_denied","mode",config.mode,"selected_transport",config.transport,"required_transport",actual,"required_permission",permission);if(spec.has("input_schema")){JsonObject checked=args.deepCopy();if(plugins.hasAction(action)){if(checked.has("plugin_revision")&&!Jsons.str(checked,"plugin_revision","").equals(Jsons.str(plugins.status(),"revision","")))return Jsons.error("plugin_revision_changed");checked.remove("plugin_revision");}Schema.validate(checked,spec.getAsJsonObject("input_schema"));}final String pinnedMode=config.mode,pinnedTransport=config.transport;Jobs.Step inner=plugins.hasAction(action)?plugins.create(action,args):Actions.create(action,args);Jobs.Step step=new PolicyStep(inner,pinnedMode,pinnedTransport);debug(action+" ["+actual+"]");return jobs.submit(id,action,args,step,epoch,Math.max(1000,Math.min(300000,Jsons.integer(args,"timeout_ms",30000))));}
 public static boolean isBuiltin(String name){return Capabilities.builtin(name);}
 public static PluginManager plugins(){return plugins;}
 /** Local settings only. No HTTP dispatch route grants compatibility overrides. */
 public static JsonObject refreshPluginsLocal(){jobs.cancelAll();Actions.stop();return plugins.reload();}
 public static JsonObject setPluginOverride(String id,String binding,boolean enabled){
  JsonObject fresh=refreshPluginsLocal();if(fresh.has("error"))return fresh;
  JsonObject target=null;for(JsonElement e:plugins.status().getAsJsonArray("plugins")){JsonObject p=e.getAsJsonObject();if(Jsons.str(p,"id","").equals(id))target=p;}
  if(target==null||!Jsons.str(target,"override_binding","").equals(binding))return Jsons.error("plugin_changed_refresh");
  if(enabled&&!Jsons.bool(target,"can_force",false))return Jsons.error("plugin_cannot_force");
  Map<String,String> before=new LinkedHashMap<>(config.pluginOverrides);
  if(enabled)config.pluginOverrides.put(id,binding);else config.pluginOverrides.remove(id);
  try{config.save(configFile);JsonObject result=plugins.reload();if(result.has("error"))throw new IllegalStateException(Jsons.str(result,"reason","plugin_reload_failed"));return result;}
  catch(Exception e){config.pluginOverrides=before;try{config.save(configFile);}catch(Exception failed){configError="plugin_override_rollback_save_failed";}plugins.reload();return Jsons.obj("error","plugin_override_failed","reason",Objects.toString(e.getMessage(),""));}
 }

 private static boolean present(String cls){try{Class.forName(cls,false,Runtime.class.getClassLoader());return true;}catch(Throwable e){return false;}}
 private static void debug(String text){long now=System.currentTimeMillis();if(config.debug&&Minecraft.getInstance().gui!=null&&now-lastDebug>200){lastDebug=now;Minecraft.getInstance().gui.getChat().addMessage(Component.literal("[MCPMCP] "+text));}}
 private static final class PolicyStep implements Jobs.Step,Jobs.Cleanup {final Jobs.Step inner;final String mode,transport;PolicyStep(Jobs.Step s,String m,String t){inner=s;mode=m;transport=t;}public JsonObject tick()throws Exception{if(!config.mode.equals(mode)||!config.transport.equals(transport))return Jsons.error("policy_changed_cancelled");return inner.tick();}public void cleanup(){if(inner instanceof Jobs.Cleanup c)c.cleanup();}}
 private Runtime(){}
}
